import{_ as e,o as a,c as i,a2 as c}from"./chunks/framework.DPTp4bo7.js";const m=JSON.parse('{"title":"萌新入坑流程及注意事项「武陵篇」","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}]]},"headers":[],"relativePath":"zh/new-player-progression-and-precautions-wuling.md","filePath":"zh/page-L0hsh88XqUwFigit3JjUTg.md"}'),p={name:"zh/new-player-progression-and-precautions-wuling.md"};function d(o,s,t,n,r,l){return a(),i("div",null,[...s[0]||(s[0]=[c(`<div class="logistics-content"><span class="logistics-source-anchor" id="萌新入坑流程及注意事项「武陵篇」" aria-hidden="true"></span><h1 id="萌新入坑流程及注意事项「武陵篇」" tabindex="-1">萌新入坑流程及注意事项「武陵篇」 <a class="header-anchor" href="#萌新入坑流程及注意事项「武陵篇」" aria-label="Permalink to &quot;萌新入坑流程及注意事项「武陵篇」&quot;">​</a></h1><blockquote><p>源页面 ID：<code>L0hsh88XqUwFigit3JjUTg</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-grey"><em>观前提醒：由于速通玩家和养老玩家在武陵地区的体验天差地别，速通玩法的流程安排及资源分配十分紧张，而养老玩法压力很小不做赘述，本篇旨在帮助速通玩家合理安排入坑流程以及资源利用。</em></span></p><p><span id="source-block-8umcWj3tmbjudi7FUj2RZm"></span></p><span class="logistics-source-anchor" id="第零阶段-进入武陵前的预备知识" aria-hidden="true"></span><h3 id="第零阶段-进入武陵前的预备知识" tabindex="-1">第零阶段：进入武陵前的预备知识 <a class="header-anchor" href="#第零阶段-进入武陵前的预备知识" aria-label="Permalink to &quot;第零阶段：进入武陵前的预备知识&quot;">​</a></h3><p>1.开号进入游戏后会有一段固定剧情，按照引导完成即可。解锁活动系统后，会有特殊活动“主线先行解锁：武陵”，接取任务即可直接进入武陵地区。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6141527773096cad.q90-531f0ac7ce0f246c.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p>2.武陵的主线任务为：景玉谷→武陵城→清波寨→首墩→应龙关→北部禁区→祀的画，其余地区均为支线地图。</p><p>3.本文提供的所有蓝图需要接水，沉积酸，惰气，息壤气的借口都在明显位置用准入口做了标签，除了特殊说明外，每个准入口对应一个水/沉积酸泵。蓝图做了大量防呆设计，不建议私自改动。</p><p>4.过任务的时候尽可能多的在地图上收集采录桩，积累工业点数。如果收集的点数不宽裕，请务必按照每阶段图示解锁，否则即使拍下蓝图也无法使用，甚至损坏蓝图中某些设备的出口设置！</p><p>5.前期调度券极其紧张，每一笔收入都要花在刀刃上，不要花在刀背，刀把，刀鞘上！</p><p>6.速通玩家的各个节点的任务进度、建设等级、矿物产出、注意事项如下图所示。本篇涉及到的所有蓝图均对应当前进度的最低矿物产出，不会出现矿物产出供不应求的现象。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8d0766297bd93b67.png" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><span id="source-block-zyNrWvjZ8IZLxWcFn70ZSH"></span></p><span class="logistics-source-anchor" id="第一阶段-主线推完武陵城-解锁武陵基地-天王坪据点" aria-hidden="true"></span><h3 id="第一阶段-主线推完武陵城-解锁武陵基地-天王坪据点" tabindex="-1">第一阶段：主线推完武陵城（解锁武陵基地，天王坪据点） <a class="header-anchor" href="#第一阶段-主线推完武陵城-解锁武陵基地-天王坪据点" aria-label="Permalink to &quot;第一阶段：主线推完武陵城（解锁武陵基地，天王坪据点）&quot;">​</a></h3><p>需要拉完景玉谷及武陵城的全部矿点，矿物的产出达到源矿250/min，蓝铁矿60/min，建设等级达到2级；顺手在基底周围获取仅1颗即可的必需植物；工业点开启图中5个；在任务中有解锁环境监测站（无需调度券），同时接到拍摄任务，获得第一桶金——12500调度券！这笔调度券需要解锁武陵城基地的存取线，在武陵城基地拍下第一张蓝图，准入口接上两个水泵，用于前期启动。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a66295804b10cfd6.q90-d4558e8f7a7f4071.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="GeNpI8CQpEYcS7V56O8qnD"><p>第一颗植物点位</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d56ea7202db7d7b0.q90-f3d02e419094ef2f.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="C0CJPrTadD1xWvzUcHcnt2"><p>工业点解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3d27564d0b8bf07b.jpeg" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="Uz6ht7pnoz4HfTy8QNjU0G"><p>武陵基地存取线解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-641556f0a417ab57.q90-c90335cc16ca6678.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="BQhHn7ewKkiPdebBvLN3sl"><p>1阶段蓝图</p></div><p><span class="mark-blue">[1阶段-武陵] EF011I96i065iU2O34O7</span></p><p>蓝图消耗180/min源矿，60/min蓝铁矿；仓库里只需要有一颗芽针及一颗砂叶就可以。启动阶段在仓库中囤积约325芽针，325砂叶，3250蓝铁零件，3250息壤；达到稳定后产出6/min低容武陵电池，3/min芽针针剂，常态1800总发电量。</p><p>然后继续过任务……</p><p><span id="source-block-vMNBmjr3Ce6UXxKUoVtfzH"></span></p><span class="logistics-source-anchor" id="第二阶段-主线推完首墩-解锁首墩据点" aria-hidden="true"></span><h3 id="第二阶段-主线推完首墩-解锁首墩据点" tabindex="-1">第二阶段：主线推完首墩（解锁首墩据点） <a class="header-anchor" href="#第二阶段-主线推完首墩-解锁首墩据点" aria-label="Permalink to &quot;第二阶段：主线推完首墩（解锁首墩据点）&quot;">​</a></h3><p>需要拉满矿点，记得补充武陵城、景玉谷新形成的矿点，矿物产出为源矿360/min，蓝铁矿90/min，赤铜矿120/min，建设等级达到5级；工业点开启图中4个；武陵基地需要扩展一次面积，增加一次基段，所需的调度券获取方法按难易程度提供：</p><pre><code>1、据点解锁就会提供一半上限的调度券囤积，兑换电池/药即可获得；

2、武陵环境监测除主线提供的一单，还有一个价值54000调度券的任务，在指定位置拍照即可；

3、武陵右下角的仓储节点需12500调度券解锁，可以接取3次11w＋调度券的订单，但由于耗时费力，不推荐。
</code></pre><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2ebedb155b0aed65.q90-1b737e24f6675274.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-df1dc00b84c258d1.q90-ad1f8ce3b68eed29.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="VxJy0HMx0zs8lekYkeDMVN"><p>工业点解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6632b360e621d9d0.q90-5a6e4f8465ba67b9.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="Pfvamu6wQOZmNZPjC1gK6B"><p>武陵区域扩大、存取线增加</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d5ce7e193670fef3.q90-3600efa888bdd011.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="HGzLPVNYwNcjTt5PxM4cOT"><p>2阶段蓝图</p></div><p><span class="mark-blue">[2阶段-武陵A] EF01081a76aE7i18E179</span></p><p><span class="mark-blue">[2阶段-武陵B] EF01i1UA57Ao52e872U4</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a2e7bb59d2dcafc2.q90-f6688770f1f4da4d.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e8e871669ce59409.q90-ec03ed451f7a0dab.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="LOa9n4FWJXuMPrsYPbkFXv"><p>蓝图摆放示意图</p></div><p>将第一张蓝图选中移到基地左上方，下方拼接2阶段A，右上方拼接2阶段B，重新接好6个水泵即可。启动后囤积3250个赤铜零件；稳定后，提供每分钟9低容电池，6优质芽针针剂，4.5芽针针剂，常态3400发电（轻微波动，不影响产线），可以满足三个据点全部升2级前的调度券兑换。</p><p><em>注意，由于2阶段是嵌入式增量蓝图，需要分取或填补一阶段产线，所以请确保一阶段蓝图完整且没有被改动！</em></p></div>`,1)])])}const b=e(p,[["render",d]]);export{m as __pageData,b as default};
